const D = { density:.5, scale:1, speed:1, energy:.6, hue:45, points:10, glow:.5, x:.5, y:.5, style:'gold', act:'unfold', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style;
const intn = (K.intensity!=null?K.intensity:0.6);
const n = Math.max(6, Math.min(12, Math.round(P.points)));
const R = u*0.135*(0.5+P.scale);
const spacing = Math.max(u*0.09, R*1.72*(1.28 - P.density*0.62));

function paintBg(buf, st, hue){
  buf.push(); buf.noStroke();
  let base;
  if (st==='ink') base=[38,10,86];
  else if (st==='blueprint') base=[214,72,14];
  else if (st==='zellige') base=[28,45,20];
  else if (st==='neon') base=[260,55,6];
  else base=[248,62,12];
  buf.background(base[0],base[1],base[2]);
  const g = buf.drawingContext.createRadialGradient(buf.width*0.5,buf.height*0.5,buf.width*0.08, buf.width*0.5,buf.height*0.5,buf.width*0.72);
  if (st==='ink'){ g.addColorStop(0,'rgba(255,255,255,0.05)'); g.addColorStop(1,'rgba(70,40,10,0.30)'); }
  else { g.addColorStop(0,'rgba(255,255,255,0.06)'); g.addColorStop(1,'rgba(0,0,0,0.42)'); }
  buf.drawingContext.fillStyle=g; buf.drawingContext.fillRect(0,0,buf.width,buf.height);
  buf.pop();
}

const key = [width,height,n,R.toFixed(1),spacing.toFixed(1),P.seed,P.x.toFixed(2),P.y.toFixed(2),st].join('|');
if (S.key !== key){
  S.key = key;
  let z = ((P.seed*2246822519)>>>0) ^ 0x9e3779b9; z=(z+2654435761)>>>0;
  const rnd = ()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  const cxN = Math.ceil(width/spacing)+2, cyN = Math.ceil(height/spacing)+2;
  const ox = (P.x-0.5)*spacing, oy=(P.y-0.5)*spacing;
  let ros=[];
  for (let gy=-1; gy<cyN; gy++) for (let gx=-1; gx<cxN; gx++){
    const cx = gx*spacing + spacing*0.5 + ox;
    const cy = gy*spacing + spacing*0.5 + oy;
    if (cx<-R||cx>width+R||cy<-R||cy>height+R) continue;
    const phi = (rnd()*0.5) + ((gx+gy)&1?Math.PI/n:0);
    ros.push({cx:cx, cy:cy, phi:phi});
  }
  // cap for perf
  if (ros.length>82){ ros.sort((a,b)=> (Math.hypot(a.cx-width/2,a.cy-height/2)) - (Math.hypot(b.cx-width/2,b.cy-height/2))); ros=ros.slice(0,82); }
  // reveal order: outward from center
  ros.sort((a,b)=> (Math.hypot(a.cx-width/2,a.cy-height/2)) - (Math.hypot(b.cx-width/2,b.cy-height/2)));
  const skip = Math.max(2, Math.round(n/3));
  const rin = R*0.42;
  const segs=[];
  for (let ri=0; ri<ros.length; ri++){
    const o=ros[ri];
    const outer=[], valley=[];
    for (let k=0;k<n;k++){ const a=o.phi+k*(2*Math.PI/n); outer.push([o.cx+Math.cos(a)*R, o.cy+Math.sin(a)*R]); }
    for (let k=0;k<n;k++){ const a=o.phi+(k+0.5)*(2*Math.PI/n); valley.push([o.cx+Math.cos(a)*rin, o.cy+Math.sin(a)*rin]); }
    const poly=[]; for (let k=0;k<n;k++){ poly.push(outer[k]); poly.push(valley[k]); }
    // star interlace ribbons: connect outer[k] -> outer[k+skip]
    for (let k=0;k<n;k++){ const b=outer[(k+skip)%n]; segs.push([outer[k][0],outer[k][1],b[0],b[1],ri]); }
    // petal ring: outer[k] -> valley[k] (single ribbon leg keeps the woven look, lighter on perf)
    for (let k=0;k<n;k++){ const a=outer[k], b=valley[k]; segs.push([a[0],a[1],b[0],b[1],ri]); }
    // connectors reaching toward neighbours
    for (let k=0;k<n;k++){ const a=o.phi+k*(2*Math.PI/n); const ex=o.cx+Math.cos(a)*(spacing*0.5), ey=o.cy+Math.sin(a)*(spacing*0.5); segs.push([outer[k][0],outer[k][1],ex,ey,ri]); }
    ros[ri].poly=poly; ros[ri].R=R;
  }
  for (let i=0;i<segs.length;i++){ const mx=(segs[i][0]+segs[i][2])*0.5, my=(segs[i][1]+segs[i][3])*0.5; segs[i].push((mx/width+my/height)*0.5); }
  S.ros=ros; S.segs=segs; S.total=ros.length; S.pal=[];
  for (let i=0;i<8;i++) S.pal.push([(P.hue + i*41 + rnd()*20)%360, 55+rnd()*30, 60+rnd()*35]);
  if (S.bg) S.bg.remove();
  S.bg = createGraphics(width,height); S.bg.colorMode(HSB,360,100,100,100); paintBg(S.bg, st, P.hue);
}

image(S.bg,0,0);

const total=S.total, segs=S.segs, ros=S.ros;
// monotonic K.t drives a smooth 30s unfold then a hold, wrapping each epoch (tolerates t0 reset)
let revealFrac = 1;
if (P.act==='unfold') revealFrac = Math.min(1, ((K.t||0) % 54) / 30);
else if (P.act==='weave') revealFrac = Math.min(1, 0.35 + 0.65*((K.t||0)%40)/22);
const revealN = Math.max(1, Math.floor(revealFrac*total));

// glow band sweeps diagonally: beat-locked + continuous K.t drift (never re-phases)
const bandC = ((K.beat*0.14*P.speed) + K.t*0.055) % 1;
const gw = 0.06 + P.glow*0.22;
const beatFlash = K.pulse*0.5 + A.rms*1.2;
const peak = 55 + P.energy*35;

if (st==='zellige'){
  noStroke();
  for (let ri=0; ri<revealN; ri++){
    const o=ros[ri], pc=S.pal[ri%S.pal.length];
    beginShape(); for (let j=0;j<o.poly.length;j++) vertex(o.poly[j][0],o.poly[j][1]); endShape(CLOSE);
    fill(pc[0], pc[1], pc[2]*(0.62+0.3*intn));
    beginShape(); for (let j=0;j<o.poly.length;j++) vertex(o.poly[j][0],o.poly[j][1]); endShape(CLOSE);
  }
}

if (st==='blueprint'){
  noFill(); stroke(205,55,50,26); strokeWeight(1);
  for (let ri=0; ri<revealN; ri++){ const o=ros[ri]; circle(o.cx,o.cy,o.R*2); circle(o.cx,o.cy,o.R*0.84); }
}

if (st==='neon'){ blendMode(ADD); }
for (let i=0;i<segs.length;i++){
  const s=segs[i]; if (s[4] >= revealN) continue;
  let dd=Math.abs(s[5]-bandC); if (dd>0.5) dd=1-dd;
  const gAmt=Math.max(0, 1 - dd/gw);
  if (st==='gold'){
    stroke(44,72,42, 90); strokeWeight(6.0*(0.6+P.scale*0.3)); line(s[0],s[1],s[2],s[3]);
    stroke((46-gAmt*8), 60-gAmt*45, 82+gAmt*18, 96); strokeWeight(2.2*(0.6+P.scale*0.3)); line(s[0],s[1],s[2],s[3]);
  } else if (st==='ink'){
    stroke(228, 16, 10, 70+gAmt*20); strokeWeight(3.4*(0.5+P.scale*0.35)*(0.7+0.5*Math.sin(i*2.1))); line(s[0],s[1],s[2],s[3]);
  } else if (st==='blueprint'){
    stroke((200 - gAmt*10), 62-gAmt*40, 78+gAmt*22, 62+gAmt*30); strokeWeight(1.3+gAmt*1.4); line(s[0],s[1],s[2],s[3]);
  } else if (st==='zellige'){
    stroke(30, 25, 8, 78); strokeWeight(2.6*(0.6+P.scale*0.3)); line(s[0],s[1],s[2],s[3]);
    if (gAmt>0){ stroke(48, 20, 100, gAmt*40); strokeWeight(1.4); line(s[0],s[1],s[2],s[3]); }
  } else if (st==='neon'){
    if (gAmt>0.35){ drawingContext.shadowBlur=12; drawingContext.shadowColor='hsla('+((P.hue)%360)+',95%,60%,0.9)'; }
    stroke((P.hue+gAmt*20)%360, 90-gAmt*30, 70+gAmt*30+peak*0.15, 55+gAmt*40); strokeWeight(1.8+gAmt*2.2); line(s[0],s[1],s[2],s[3]);
    drawingContext.shadowBlur=0;
  }
}

// central beat bloom on revealed rosettes (partial-frame, not a full flash)
if (beatFlash>0.05){
  noStroke();
  const bh = st==='neon'?(P.hue)%360:(st==='ink'?38:46);
  blendMode(ADD);
  for (let ri=0; ri<revealN; ri++){ const o=ros[ri]; fill(bh, st==='ink'?30:40, 100, beatFlash*14); circle(o.cx,o.cy, o.R*0.5*(1+beatFlash*0.3)); }
  blendMode(BLEND);
}

blendMode(BLEND);
drawingContext.shadowBlur = 0;
